303	/**
304	 * A claim's status. It starts as DRAFT, is opened (OPEN) and then settled (SETTLED). A clerk's
305	 * settle above the clerk limit makes it PENDING instead, until a steward approves it (SETTLED) or
306	 * rejects it (back to OPEN). A DRAFT, OPEN or PENDING claim can be voided (VOID); a SETTLED one
307	 * too, by a steward within days of its settlement ({@link VoidClaim}). VOID is final. A DRAFT claim can be deleted
308	 * (DELETED), and made a DRAFT again by a restore on the sheet's today it was deleted ({@link RestoreClaim}). Only OPEN, PENDING and SETTLED claims count toward any total.
309	 */
310	public enum ClaimStatus {
311	    DRAFT(null), OPEN("CLAIM_OPENED"), PENDING("CLAIM_PENDING"), SETTLED("CLAIM_SETTLED"), VOID("CLAIM_VOIDED"),
312	    DELETED("CLAIM_DELETED");
313	
314	    private final String auditEvent;
315	
316	    ClaimStatus(String auditEvent) {
317	        this.auditEvent = auditEvent;
318	    }
319	
320	    /** The audit event written when a claim moves into this status. */
321	    public String auditEvent() {
322	        return auditEvent;
323	    }
324	
325	    /** Whether a claim in this status may move to {@code next}. */
326	    public boolean canMoveTo(ClaimStatus next) {
327	        return switch (next) {
328	            case OPEN -> this == DRAFT;
329	            case PENDING -> this == OPEN;
330	            case SETTLED -> this == OPEN;
331	            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == SETTLED;
332	            case DELETED -> this == DRAFT;
333	            case DRAFT -> this == DELETED;
334	        };
335	    }
336	}

