    15	
    16	/**
    17	 * Settles the claim and fixes its due: its amount times the rate of its person's grade in force on its date, in force on the
    18	 * claim's date, divided by 100 and rounded to two decimals as the claim rounds (by the sheet's policy date), or
    19	 * for a claim a statement bound its bound figure; with the late charge it has gained on that figure
    20	 * by the sheet's today frozen in on top, and at least the floor in force on its date (applied last).
    21	 * With no such rate the due is not fixed. The user who opened the claim, or last edited it, may not settle it.
    22	 * When a clerk (any user not made a steward) settles a claim whose due is above the sheet's clerk
    23	 * limit, it goes to PENDING instead, its due left live until a steward approves or rejects it; a
    24	 * due of n/a is within any limit. Before the clerk limit is considered, a claim whose due is above
    25	 * the proof threshold in force on its date is refused while it has no proofs. Only a role the
    26	 * permission matrix allows may settle.
    27	 */
    28	public class SettleClaim {
    29	    public void apply(@Val Sheet sheet, @Val Claim claim, PersonRepository people, RateRepository rates,
    30	            RoleRepository roles, SettingsRepository settingsStore, HttpServletRequest request)
    31	            throws InvalidClaimStatusException, SelfSettleException {
    32	        settle(sheet, claim, Audit.user(request), people, rates, roles, settingsStore);
    33	        claim.setSettleBatch(null); // settled one at a time: in no batch
    34	    }
    35	
    36	    /** Settles the claim as the given user would, by the rules above; throws when it may not. */
    37	    static void settle(Sheet sheet, Claim claim, String user, PersonRepository people, RateRepository rates,
    38	            RoleRepository roles, SettingsRepository settingsStore)
    39	            throws InvalidClaimStatusException, SelfSettleException {
    40	        Person person = people.find(sheet.id(), claim.getPersonId());
    41	        Settings settings = settingsStore.find(sheet.id());
    42	        String role = roles.roleOf(sheet.id(), user);
    43	        if (!settings.allows("settle", role)) {
    44	            throw new InvalidClaimStatusException("A " + role + " may not settle a claim");
    45	        }
    46	        String grade = person.gradeOn(claim.getDate());
    47	        BigDecimal figure = claim.isStated() ? claim.getStatedDue()
    48	                : ClaimFigure.live(claim, rates.findAll(sheet.id()), grade, settings, sheet.today());
    49	        // The late charge is read while the claim is still OPEN.
    50	        BigDecimal late = ClaimFigure.late(claim, figure, grade, settings, sheet.today());
    51	        if (claim.isDeferredOn(sheet.today())) {
    52	            throw new InvalidClaimStatusException("A claim deferred until " + claim.getDeferredUntil() + " cannot be settled");
    53	        }
    54	        if (!claim.getStatus().canMoveTo(ClaimStatus.SETTLED)) {
    55	            throw new InvalidClaimStatusException(claim.getStatus(), ClaimStatus.SETTLED);
    56	        }
    57	        if (user.equals(claim.getOpenedBy())) throw new SelfSettleException(user);
    58	        if (claim.isOwnedBy(user)) throw new SelfSettleException(user, "last edited");
    59	        BigDecimal due = ClaimFigure.floored(claim, figure, late, settings);
    60	        if (settings.needsProof(due, grade, claim.getDate(), claim.getProofs())) throw new InvalidClaimStatusException(ProofRequired.MESSAGE);
    61	        if (!settings.withinClerkLimit(due, sheet.today()) && Role.CLERK.equals(role)) {
    62	            claim.moveTo(ClaimStatus.PENDING);
    63	            return;
    64	        }
    65	        claim.moveTo(ClaimStatus.SETTLED);
    66	        claim.setSettledDue(due);
    67	    }
    68	}
