    15	/**
    16	 * Approves a PENDING claim: it is settled, its due fixed at this moment at its live figure (a
    17	 * PENDING claim is bound by no statement) with the late charge it has gained by the sheet's today.
    18	 * Only a steward may approve it, and not the user who opened it or last edited it; and not while it has no proofs
    19	 * when its due is above the proof threshold in force on its date.
    20	 */
    21	public class ApproveClaim {
    22	    public void apply(@Val Sheet sheet, @Val Claim claim, PersonRepository people, RateRepository rates,
    23	            RoleRepository roles, SettingsRepository settings, HttpServletRequest request)
    24	            throws InvalidClaimStatusException, ApprovalException {
    25	        if (claim.getStatus() != ClaimStatus.PENDING) {
    26	            throw new InvalidClaimStatusException(claim.getStatus(), ClaimStatus.SETTLED);
    27	        }
    28	        String user = Audit.user(request);
    29	        if (!Role.STEWARD.equals(roles.roleOf(sheet.id(), user))) {
    30	            throw new ApprovalException("Only a steward may approve a claim: " + user + " is a clerk");
