13: /**
14:  * Only a steward by their own role may delegate (not one acting as a steward by a delegation). A blank
15:  * from-date is the sheet's today, a blank to-date the from-date; a to-date before the from-date is refused.
16:  */
17: public class SaveDelegation {
18:     public void save(@Val DelegationInput input, @Val Sheet sheet, RoleRepository roles,
19:             DelegationRepository repository, HttpServletRequest request, Out<Delegation> delegationOut)
20:             throws InvalidDelegationException {
21:         String by = Audit.user(request);
