22:         String raw = request == null ? null : request.getHeader(HEADER);
23:         if (raw == null || raw.isBlank()) return null;
24:         try {
25:             return LocalDate.parse(raw.trim());
26:         } catch (DateTimeParseException e) {
27:             return null;
