43:     }
45:     /** Archive the sheet: true when this call archived it, false when it already was. */
46:     public boolean archive(String id) {
47:         return jdbc.update("UPDATE sheet SET archived = TRUE, archived_on = today WHERE id = ? AND archived = FALSE", id) > 0;
48:     }
50:     /**
51:      * The sheet as it stood at the end of {@code day}: that date stands in for its today, and it is
52:      * archived only when it was archived while its today was on or before it.
53:      */
