55:         List<Boolean> archived = jdbc.query("SELECT archived AND (archived_on IS NULL OR archived_on <= ?) AS archived_then"
56:                 + " FROM sheet WHERE id = ?", (rs, n) -> rs.getBoolean("archived_then"), Date.valueOf(day), sheet.id());
57:         return new Sheet(sheet.id(), day, !archived.isEmpty() && archived.get(0));
58:     }
60:     /** The sheet's parent sheet's id, or null when it has none (or was never loaded). */
61:     public String parent(String id) {
62:         List<String> found = jdbc.query("SELECT parent_id FROM sheet WHERE id = ?",
63:                 (rs, n) -> rs.getString("parent_id"), id);
64:         return found.isEmpty() ? null : found.get(0);
65:     }
67:     /** The ids of the sheets naming this one as their parent, in id order. */
68:     public List<String> children(String id) {
69:         return jdbc.query("SELECT id FROM sheet WHERE parent_id = ? ORDER BY id", (rs, n) -> rs.getString("id"), id);
70:     }
72:     /**
73:      * The sheets of the sheet's tree, not the sheet itself: its ancestors (its parent, theirs and so
74:      * on) and its descendants (the sheets naming it as their parent, those naming them and so on),
75:      * among the sheets that exist, each once.
76:      */
77:     public java.util.Set<String> tree(String id) {
78:         java.util.Set<String> seen = new java.util.LinkedHashSet<>(List.of(id));
79:         for (String at = parent(id); at != null && seen.add(at); at = parent(at)) {
80:             // walked up to the root, stopping at a sheet already seen
81:         }
82:         java.util.Deque<String> pending = new java.util.ArrayDeque<>(List.of(id));
83:         while (!pending.isEmpty()) {
84:             for (String child : children(pending.removeFirst())) {
85:                 if (seen.add(child)) pending.addLast(child);
86:             }
87:         }
88:         seen.remove(id);
89:         return seen;
90:     }
