93:      * The sheet's descendants (the sheets naming it as their parent, those naming them and so on),
94:      * each once and never the sheet itself, in id order.
95:      */
96:     public List<String> descendants(String id) {
97:         java.util.Set<String> seen = new java.util.TreeSet<>();
98:         java.util.Deque<String> pending = new java.util.ArrayDeque<>(List.of(id));
99:         while (!pending.isEmpty()) {
100:             for (String child : children(pending.removeFirst())) {
101:                 if (!child.equals(id) && seen.add(child)) pending.addLast(child);
102:             }
103:         }
104:         return new java.util.ArrayList<>(seen);
105:     }
