26: /**
27:  * Clones the sheet to another id (a steward), only one never used. The clone gets this sheet's today,
28:  * settings, roles, rates, holidays, void reasons, templates, people, pools and periods (all open; see
29:  * {@link SheetCloneRepository}), then each person's claims, oldest listed first, with their status,
30:  * frozen figures, dates, notes and logs. Each claim that had a number takes the clone's next, in the
31:  * order the claims were opened (by the sheet's today then, then the order added to the clone); a
32:  * correction or split names the new numbers. Statements are not copied.
33:  */
34: public class CloneSheet {
35:     public void cloneSheet(@Val CloneInput input, @Val Sheet sheet, SheetRepository sheets, SheetCloneRepository copier,
36:             PersonRepository people, ClaimRepository claims, RoleRepository roles, SettingsRepository settings,
37:             PeriodRepository periods, HttpServletRequest request, Out<Clone> cloneOut)
38:             throws StewardOnlyException, InvalidSheetIdException {
39:         if (!Role.STEWARD.equals(roles.roleOf(sheet.id(), Audit.user(request)))) {
40:             throw new StewardOnlyException("Only a steward may clone the sheet");
41:         }
42:         if (sheets.find(input.toSheet()) != null) {
43:             throw new InvalidSheetIdException("A sheet can only be cloned to an id never used");
44:         }
45:         Map<Long, Long> copies = copier.copy(sheet.id(), input.toSheet());
46:         Sheet to = sheets.find(input.toSheet());
47:         Settings toSettings = settings.find(to.id());
49:         List<Claim> copied = new ArrayList<>();
50:         Map<Long, Long> copyOf = new HashMap<>();
51:         for (Person person : people.findAll(sheet.id())) {
52:             List<Claim> theirs = new ArrayList<>(claims.findByPerson(sheet.id(), person.getId()));
53:             Collections.reverse(theirs);
54:             for (Claim claim : theirs) {
55:                 copyOf.put(claim.getId(), claims.copy(claim, to.id(), copies.get(person.getId())));
56:                 copied.add(claim);
57:             }
58:         }
59:         Map<Long, LocalDate> openedOn = new HashMap<>();
60:         List<Claim> numbered = new ArrayList<>();
61:         for (Claim claim : copied) {
62:             if (claim.getNumber() == null) continue;
63:             LocalDate opened = claims.openedOn(claim);
64:             openedOn.put(claim.getId(), opened == null ? claim.getDate() : opened);
65:             numbered.add(claim);
66:         }
67:         numbered.sort(Comparator.comparing((Claim c) -> openedOn.get(c.getId()))
68:                 .thenComparing((Claim c) -> copyOf.get(c.getId())));
69:         Map<String, String> renumbered = new HashMap<>();
70:         Map<Long, String> numbers = new HashMap<>();
71:         for (Claim claim : numbered) {
72:             String number = ClaimNumbers.next(to, claim, toSettings, periods, claims);
73:             renumbered.put(claim.getNumber(), number);
74:             numbers.put(claim.getId(), number);
75:         }
76:         for (Claim claim : copied) {
77:             claims.numberCopy(to.id(), copyOf.get(claim.getId()), numbers.get(claim.getId()),
78:                     claim.getCorrects() == null ? null : renumbered.getOrDefault(claim.getCorrects(), claim.getCorrects()),
79:                     claim.getSplitFrom() == null ? null : renumbered.getOrDefault(claim.getSplitFrom(), claim.getSplitFrom()));
80:         }
81:         cloneOut.set(new Clone(to));
82:     }
83: }
