    11	/**
    12	 * A claim's figures, as the screen shows them. Its rate figure: the figure its person's last
    13	 * statement bound it to (never while it is PENDING), else its amount times its grade's rate in
    14	 * force on its date, divided by 100 and rounded to two decimals. Its live due: the greater of the
    15	 * sheet's floor in force on its date and its rate figure plus its late charge (worked out on the
    16	 * rate figure alone); a correction, a negative amount, has no floor and no late charge. A settled
    17	 * claim's due stays as it was fixed. Null for n/a (no floor applies to n/a). Every rounding of a
    18	 * claim's live figures is by the sheet's policy date ({@link Settings#rounding}): half up when the
    19	 * claim is dated before it, half to even on or after; a correction rounds by the date of the claim
    20	 * it corrects.
    21	 */
    22	public final class ClaimFigure {
    23	    private ClaimFigure() {}
    24	
    25	    /** The claim's rate figure: its bound figure when a statement bound it, else its live rate figure. */
    26	    public static BigDecimal of(Claim claim, List<Rate> rates, String grade, Settings settings, LocalDate today) {
    27	        if (claim.isBound()) return claim.getStatedDue();
    28	        return live(claim, rates, grade, settings, today);
    29	    }
    30	
    31	    /** The claim's amount at its grade's rate on its date, before any floor or late charge. */
    32	    public static BigDecimal live(Claim claim, List<Rate> rates, String grade, Settings settings, LocalDate today) {
    33	        RoundingMode mode = rounding(claim, settings, today);
    34	        return Rate.inForce(rates, grade, claim.getDate())
    35	                .map((pct) -> times(claim.getAmount(), pct, mode))
    36	                .orElse(null);
    37	    }
    38	
    39	    /**
    40	     * The due on a rate figure with a late charge: the greater of the floor in force on the claim's
    41	     * date and the figure plus the charge; a correction has no floor. Null for n/a.
    42	     */
    43	    public static BigDecimal floored(Claim claim, BigDecimal figure, BigDecimal late, Settings settings) {
    44	        if (figure == null) return null;
    45	        BigDecimal due = figure.add(late);
    46	        return claim.isCorrection() ? due : due.max(settings.floorOn(claim.getDate()));
    47	    }
    48	
    49	    /** How the claim's live figures round, by the date it rounds by and the sheet's policy date. */
    50	    public static RoundingMode rounding(Claim claim, Settings settings, LocalDate today) {
    51	        return settings.rounding(claim.getRoundDate(), today);
    52	    }
    53	
    54	    /**
    55	     * The claim's due as the screen shows it: the due fixed when it was settled, else its live due
    56	     * ({@link #floored}) on its rate figure ({@link #of}) and the late charge an OPEN or PENDING claim
    57	     * gains on that figure while overdue on {@code today}. Null for n/a.
    58	     */
    59	    public static BigDecimal withLate(Claim claim, List<Rate> rates, String grade, Settings settings,
    60	            LocalDate today) {
    61	        if (claim.getSettledDue() != null) return claim.getSettledDue();
    62	        BigDecimal figure = of(claim, rates, grade, settings, today);
    63	        return figure == null ? null : floored(claim, figure, late(claim, figure, grade, settings, today), settings);
    64	    }
    65	
    66	    /**
    67	     * The late charge on a figure: for an OPEN or PENDING claim past its due-by (fixed when it was made)
    68	     * plus the grace days of its grade ({@code grade}, the one in force on its date) on its date
    69	     * ({@link Settings#overdueFrom}) on {@code today}, for every full 30 days it is overdue the
    70	     * sheet's late percent in force on that boundary date (that day plus 30, 60, 90 ... days) of the figure plus the
    71	     * charges of the boundaries before it (compounding), each rounded to two
    72	     * decimals as the claim rounds, added up; else 0.00 (as for a claim deferred on today). Never bound by a statement:
    73	     * it follows the sheet's today until the claim is settled.
    74	     */
    75	    public static BigDecimal late(Claim claim, BigDecimal figure, String grade, Settings settings, LocalDate today) {
    76	        if (!claim.isOpen() || claim.isDeferredOn(today)) return BigDecimal.ZERO.setScale(2);
    77	        return lateAsOpen(claim, figure, grade, settings, today);
    78	    }
    79	
    80	    /** The late charge on a figure as {@link #late} reads it for an open claim, whatever the claim's status. */
    81	    public static BigDecimal lateAsOpen(Claim claim, BigDecimal figure, String grade, Settings settings,
    82	            LocalDate today) {
    83	        BigDecimal none = BigDecimal.ZERO.setScale(2);
    84	        if (figure == null || claim.isCorrection()) return none;
    85	        LocalDate from = settings.overdueFrom(claim.getDueBy(), grade, claim.getDate());
    86	        long overdue = ChronoUnit.DAYS.between(from, today);
    87	        long periods = overdue > 0 ? overdue / 30 : 0;
    88	        RoundingMode mode = rounding(claim, settings, today);
    89	        BigDecimal charge = none;
    90	        for (long k = 1; k <= periods; k++) {
    91	            BigDecimal pct = settings.latePctOn(from.plusDays(30 * k));
    92	            if (pct.signum() != 0) charge = charge.add(times(figure.add(charge), pct, mode));
    93	        }
    94	        return charge;
    95	    }
    96	
    97	    /** The amount times the percent, divided by 100 and rounded to two decimals. */
    98	    private static BigDecimal times(BigDecimal amount, BigDecimal pct, RoundingMode mode) {
    99	        return amount.multiply(pct).divide(BigDecimal.valueOf(100), 2, mode);
