18: /**
19:  * Gives each selected person, in list order (the order they were added), the grade from the
20:  * from-date exactly as the person form would (see {@link ApplyPerson}): their name and terms are
21:  * kept, and a grade left as the row shows it with the from-date blank records nothing. Each is
22:  * audited as a single edit is: its PERSON_EDITED line, then the figures it moved. A viewer, or anyone
23:  * on an archived sheet, has every selected person refused: none is graded and nothing is written.
24:  */
25: public class GradeSelectedPeople {
26:     public void grade(@Val Sheet sheet, @Val BulkGradeRequest request, PersonRepository people,
27:             ClaimRepository claims, RateRepository rates, SettingsRepository settings, RoleRepository roles, HttpServletRequest http,
28:             Audit audit, Out<BulkGradeResponse> result) {
29:         String user = Audit.user(http);
30:         if (sheet.archived() || Role.VIEWER.equals(roles.roleOf(sheet.id(), user))) {
31:             result.set(new BulkGradeResponse(0));
32:             return;
33:         }
34:         Set<Long> selected = new HashSet<>();
35:         for (String id : request.personIds()) {
36:             try {
37:                 selected.add(Long.parseLong(id.trim()));
38:             } catch (NumberFormatException | NullPointerException e) {
39:                 // not an id: no person on the sheet
40:             }
41:         }
42:         boolean dated = !request.gradeFrom().isEmpty();
43:         Rollup before = rollup(sheet, people, claims, rates, settings);
44:         int graded = 0;
45:         for (Person person : people.findAll(sheet.id())) {
46:             if (!selected.contains(person.getId())) continue;
47:             if (dated || !request.grade().equals(person.gradeOn(sheet.today()))) {
48:                 person.setGradeFrom(request.grade(), dated ? LocalDate.parse(request.gradeFrom()) : sheet.today());
49:             }
50:             // Saved over by someone else since it was read: left as it is.
51:             if (!people.save(person)) continue;
52:             graded++;
53:             audit.record("PERSON_EDITED sheet=" + sheet.id() + " by=" + user + " name=" + person.getName()
54:                     + " grade=" + person.gradeOn(sheet.today()));
55:             Rollup after = rollup(sheet, people, claims, rates, settings);
56:             after.changesSince(before, sheet.id(), user).forEach(audit::record);
57:             before = after;
58:         }
59:         result.set(new BulkGradeResponse(graded));
60:     }
62:     private static Rollup rollup(Sheet sheet, PersonRepository people, ClaimRepository claims, RateRepository rates,
63:             SettingsRepository settings) {
64:         return Rollup.of(sheet.id(), sheet.today(), people, claims, rates, settings.find(sheet.id()));
65:     }
66: }
