22: /**
23:  * Takes the person's statement: their due-total now (the figures of their claims that count, added
24:  * up, skipping n/a; n/a when their grade in force today has no rate today and no claim that counts keeps a fixed
25:  * figure, has one under another grade in force on its date, or has one dated on or before today (under a
26:  * rate that has since ended); held to the sheet's cap; each claim at its date's grade's rate; an overdue claim's late charge on top), as the screen shows it. Every claim of theirs that counts is bound to its rate figure now
27:  * (a live one before the floor), never its late charge nor the floor;
28:  * every other claim of theirs is left unbound (live). The person's statement count goes up by one,
29:  * and the due-total and the sheet's today are kept as the last statement's.
30:  * <p>
31:  * Taken as of a date (on or before the sheet's today, and not before the person was added), it is
32:  * taken as the sheet stood at the end of that date: every change made while the sheet's today was
33:  * on or before it counts (the rates, settings, the person's grades, holds and retirement, each
34:  * claim's status, settled due and statement binding), every later change does not, and the date
35:  * stands in for the sheet's today in every figure. That date is kept as the statement's date.
36:  */
37: public class TakeStatement {
38:     public void take(@Val Sheet sheet, @Val Person person, @Val StatementInput input, ClaimRepository claims,
39:             ClaimLogRepository logs, RateRepository rates, SettingsRepository settings, PersonRepository people,
40:             Out<Statement> statementOut) throws InvalidStatementException {
41:         LocalDate asOf = input.asOf();
42:         if (asOf != null && asOf.isAfter(sheet.today())) {
43:             throw new InvalidStatementException("A statement is taken as of a date on or before today");
44:         }
45:         if (asOf != null && !person.addedBy(asOf)) {
46:             throw new InvalidStatementException(person.getName() + " was not yet added on " + asOf);
47:         }
48:         LocalDate today = asOf != null ? asOf : sheet.today();
49:         List<Rate> all = asOf != null ? rates.findAsOf(sheet.id(), asOf) : rates.findAll(sheet.id());
50:         Settings sheetSettings = asOf != null ? settings.findAsOf(sheet.id(), asOf) : settings.find(sheet.id());
51:         Person then = asOf != null ? people.asOf(person, asOf) : person;
52:         Map<Long, ClaimLogRepository.Line> lines = asOf != null ? logs.linesOn(sheet.id(), asOf) : null;
53:         Map<Long, ClaimRepository.Binding> bindings = asOf != null ? claims.bindingsOn(sheet.id(), asOf) : null;
54:         BigDecimal total = BigDecimal.ZERO.setScale(2);
55:         boolean fixed = false;
56:         int counted = 0;
57:         for (Claim live : claims.findByPerson(sheet.id(), person.getId())) {
58:             Claim claim = live;
59:             if (asOf != null) {
60:                 ClaimLogRepository.Line line = lines.get(live.getId());
61:                 ClaimRepository.Binding binding = bindings.get(live.getId());
62:                 claim = line == null ? null : live.asThen(line.status(),
63:                         line.status() == ClaimStatus.SETTLED ? line.due() : null,
64:                         binding != null && binding.stated(), binding == null ? null : binding.statedDue());
65:             }
66:             boolean counts = claim != null && claim.counts(then.heldOn(claim.getDate(), today), today);
67:             if (counts) {
68:                 counted++;
69:                 if (claim.getSettledDue() != null || claim.boundDue() != null) fixed = true;
70:                 String grade = then.gradeOn(claim.getDate());
71:                 BigDecimal figure = claim.getSettledDue() != null ? claim.getSettledDue()
72:                         : ClaimFigure.of(claim, all, grade, sheetSettings, today);
73:                 // A figure found under a grade other than today's is kept, whatever today's rate.
74:                 if (figure != null && !grade.equals(then.gradeOn(today))) fixed = true;
75:                 // So is one dated on or before today, found under a rate that has since ended.
76:                 if (figure != null && !claim.getDate().isAfter(today)) fixed = true;
77:                 // The due-total carries the late charge and the floor; the claim is bound to the rate figure under them.
78:                 BigDecimal due = ClaimFigure.withLate(claim, all, grade, sheetSettings, today);
79:                 if (due != null) total = total.add(due);
80:                 live.bind(true, figure);
81:             } else {
82:                 live.bind(false, null);
83:             }
84:             claims.save(live);
85:         }
86:         String dueTotal = Rate.inForce(all, then.gradeOn(today), today).isEmpty() && !fixed
87:                 ? "n/a" : sheetSettings.capped(total, today).toPlainString();
88:         person.setStatements(person.getStatementCount() + 1, dueTotal, today);
89:         people.saveStatements(person);
90:         statementOut.set(new Statement(dueTotal, counted, asOf));
91:     }
92: }
