18: /**
19:  * The sheet's figures as the screen shows them: each person's claimed, due-total and overdue-total (by person id,
20:  * in the order they were added), and the sheet's claimed-total, due-total and overdue-total, and the sheet's alert
21:  * threshold (null: off).
22:  */
23: public record Rollup(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal,
24:         BigDecimal alertThreshold) {
26:     /** A person's figures: their name, claimed, due-total (n/a when none) and overdue-total. */
27:     public record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
28:         boolean sameFigures(Figures other) {
29:             return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal)
30:                     && overdueTotal.equals(other.overdueTotal);
31:         }
33:         /** Whether their due-total is above a threshold (never when they have none). */
34:         boolean above(BigDecimal threshold) {
35:             return !"n/a".equals(dueTotal) && new BigDecimal(dueTotal).compareTo(threshold) > 0;
36:         }
37:     }
39:     /**
40:      * The sheet's figures now. A person's claimed is the amounts of their claims that count (OPEN
41:      * and SETTLED, but not an unbound OPEN one dated within one of their holds, nor a correction) added up; their due-total the figures of those claims added up, skipping n/a (a live due is the greater of the floor on its date and its rate figure plus the late
42:      * charge it gains on {@code today}), and
43:      * n/a when their grade in force today has no rate today and no claim that counts keeps a fixed
44:      * figure or has one under the grade in force on its date when that is another grade, or
45:      * has one dated on or before today (under a rate that has since ended), held to the sheet's cap. Each claim
46:      * takes the rate of the grade in force on its date. The
47:      * sheet's totals add these up, skipping n/a; with three or more figures, the due-total and
48:      * overdue-total leave out the single highest and the single lowest.
49:      */
50:     public static Rollup of(String sheetId, LocalDate today, PersonRepository people, ClaimRepository claims,
51:             RateRepository rates, Settings settings) {
52:         List<Rate> all = rates.findAll(sheetId);
53:         List<Claim> sheetClaims = claims.findAll(sheetId);
54:         Map<Long, Figures> figures = new LinkedHashMap<>();
55:         BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
56:         List<BigDecimal> dues = new ArrayList<>();
57:         List<BigDecimal> overdues = new ArrayList<>();
58:         for (Person person : people.findAll(sheetId)) {
59:             BigDecimal claimed = BigDecimal.ZERO.setScale(2);
60:             BigDecimal due = BigDecimal.ZERO.setScale(2);
61:             BigDecimal overdue = BigDecimal.ZERO.setScale(2);
62:             boolean fixed = false;
63:             for (Claim claim : sheetClaims) {
64:                 if (claim.getPersonId() != person.getId()) continue;
65:                 if (!claim.counts(person.heldOn(claim.getDate(), today), today)) continue;
66:                 if (!claim.isCorrection()) claimed = claimed.add(claim.getAmount());
67:                 if (claim.getSettledDue() != null || claim.boundDue() != null) fixed = true;
68:                 String grade = person.gradeOn(claim.getDate());
69:                 BigDecimal figure = ClaimFigure.withLate(claim, all, grade, settings, today);
70:                 if (figure != null) due = due.add(figure);
71:                 if (figure != null && overdue(claim, grade, settings, today)) overdue = overdue.add(figure);
72:                 // A figure found under a grade other than today's is kept, whatever today's rate.
73:                 if (figure != null && !grade.equals(person.gradeOn(today))) fixed = true;
74:                 // So is one dated on or before today, found under a rate that has since ended.
75:                 if (figure != null && !claim.getDate().isAfter(today)) fixed = true;
76:             }
77:             boolean none = Rate.inForce(all, person.gradeOn(today), today).isEmpty() && !fixed;
78:             claimedTotal = claimedTotal.add(claimed);
79:             overdues.add(overdue);
80:             due = settings.capped(due, today);
81:             if (!none) dues.add(due);
82:             figures.put(person.getId(), new Figures(person.getName(), show(claimed), none ? "n/a" : show(due),
83:                     show(overdue)));
84:         }
85:         return new Rollup(figures, show(claimedTotal), show(trimmed(dues)), show(trimmed(overdues)),
86:                 settings.alertThreshold());
87:     }
89:     /** People's figures added up: with three or more, the single highest and single lowest left out. */
90:     private static BigDecimal trimmed(List<BigDecimal> values) {
91:         List<BigDecimal> sorted = new ArrayList<>(values);
92:         sorted.sort(BigDecimal::compareTo);
93:         if (sorted.size() >= 3) sorted = sorted.subList(1, sorted.size() - 1);
94:         return sorted.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
95:     }
97:     /**
98:      * Whether a claim is overdue on {@code today}: open (OPEN or PENDING) and past its due-by plus the
99:      * grace days of its grade on its date ({@link Settings#overdueFrom}).
100:      */
101:     private static boolean overdue(Claim claim, String grade, Settings settings, LocalDate today) {
102:         return claim.isOpen() && today != null && claim.getDueBy() != null
103:                 && settings.overdueFrom(claim.getDueBy(), grade, claim.getDate()).isBefore(today);
104:     }
106:     /**
107:      * The audit lines for the move from {@code before} to this: one ROLLUP line per person whose
