47:      * Fixes the open (or soft-closed) period's due-total, and each person's, as at the sheet's today,
48:      * and marks it closed, or soft-closed when {@code soft}, in the store: the closed period, or null
49:      * when another request changed it first.
50:      */
51:     static Period fix(Sheet sheet, Period period, boolean soft, PeriodRepository periods, PersonRepository people,
52:             ClaimRepository claims, ClaimLogRepository log, RateRepository rates, SettingsRepository settings) {
53:         List<Rate> all = rates.findAll(sheet.id());
54:         Settings sheetSettings = settings.find(sheet.id());
55:         List<Claim> sheetClaims = claims.findAll(sheet.id());
56:         Map<Long, ClaimStatus> statusesThen = log.statusesOn(sheet.id(), period.to());
57:         BigDecimal total = BigDecimal.ZERO.setScale(2);
58:         Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
59:         for (Person person : people.findAll(sheet.id())) {
60:             BigDecimal personTotal = BigDecimal.ZERO.setScale(2);
61:             for (Claim claim : sheetClaims) {
62:                 if (claim.getPersonId() != person.getId() || !period.contains(claim.getDueBy())) continue;
63:                 if (!claim.countsAsOf(statusesThen.get(claim.getId()), person.heldOn(claim.getDate(), sheet.today()), sheet.today())) continue;
64:                 BigDecimal figure = ClaimFigure.withLate(claim, all, person.gradeOn(claim.getDate()), sheetSettings, sheet.today());
65:                 if (figure != null) personTotal = personTotal.add(figure);
66:             }
67:             personTotals.put(person.getId(), personTotal);
68:             total = total.add(personTotal);
69:         }
70:         Period closed = soft ? period.softClose(total) : period.close(total);
71:         if (!periods.markClosed(closed, period.soft())) return null;
72:         periods.deletePersonTotals(closed);
73:         periods.savePersonTotals(closed, personTotals);
74:         return closed;
75:     }
76: }
