8: /**
9:  * A period's cap on open claims: a claim belongs to the period containing its due-by, and while
10:  * that period has a cap, its person may have at most that many OPEN or PENDING claims in it.
11:  */
12: public final class PeriodCaps {
13:     private PeriodCaps() {
14:     }
16:     /** The capped period the claim belongs to when its person is already at the cap, else null. */
17:     public static Period full(Sheet sheet, Claim claim, PeriodRepository periods, ClaimRepository claims) {
18:         if (claim.getDueBy() == null) return null;
19:         Period period = periods.on(sheet.id(), claim.getDueBy());
20:         if (period == null || period.cap() == null) return null;
21:         long held = claims.findByPerson(sheet.id(), claim.getPersonId()).stream()
22:                 .filter(c -> !c.getId().equals(claim.getId()))
23:                 .filter(c -> c.getStatus() == ClaimStatus.OPEN || c.getStatus() == ClaimStatus.PENDING)
24:                 .filter(c -> c.getDueBy() != null && period.contains(c.getDueBy()))
25:                 .count();
26:         return held >= period.cap() ? period : null;
27:     }
28: }
