12: /**
13:  * Makes one period per calendar month from the from-date's month to the to-date's month (a blank
14:  * from-date is the sheet's today), each running from the first to the last day of its month and
15:  * named yyyy-mm. A to-date before the from-date is refused. A month whose name is already a period,
16:  * or whose days overlap a period on the sheet, is left out; each made is saved and audited in turn.
17:  */
18: public class GeneratePeriods {
19:     public void generate(@Val GeneratePeriodsInput input, @Val Sheet sheet, PeriodRepository repository,
20:             HttpServletRequest request, Audit audit, Out<GeneratePeriodsResponse> result)
21:             throws InvalidPeriodException {
22:         LocalDate from = input.from() == null ? sheet.today() : input.from();
23:         if (input.to().isBefore(from)) {
24:             throw new InvalidPeriodException("A to-date is on or after the from-date");
25:         }
26:         result.set(new GeneratePeriodsResponse(months(from, input.to(), sheet, repository, request, audit)));
27:     }
29:     /** Makes and audits the monthly periods from the from-date's month to the to-date's month, as above: how many were made. */
30:     static int months(LocalDate from, LocalDate to, Sheet sheet, PeriodRepository repository,
31:             HttpServletRequest request, Audit audit) {
32:         List<Period> existing = repository.findAll(sheet.id());
33:         int made = 0;
34:         for (YearMonth month = YearMonth.from(from); !month.isAfter(YearMonth.from(to)); month = month.plusMonths(1)) {
35:             Period period = new Period(sheet.id(), month.toString(), month.atDay(1), month.atEndOfMonth());
36:             if (existing.stream().anyMatch(o -> o.name().equals(period.name()) || o.overlaps(period))) continue;
37:             repository.insert(period);
38:             audit.record("PERIOD_ADDED sheet=" + sheet.id() + " by=" + Audit.user(request)
39:                     + " period=" + period.name() + " from=" + period.from() + " to=" + period.to());
40:             made++;
41:         }
42:         return made;
43:     }
44: }
