29: /**
30:  * Adds a DRAFT claim per pasted line, in order, for the person on the sheet with that name (matched
31:  * as names are compared). Every line is checked first, as the claim form checks a claim (its person
32:  * on the sheet, its reference unused on the sheet and in the paste, its due-by outside a closed period and not after its person's retirement), so a
33:  * refused paste writes nothing; then each claim is saved, logged and audited as one added by the form.
34:  */
35: public class AddPastedClaims {
36:     public void add(@Val Sheet sheet, @Val PasteLines paste, PersonRepository people, ClaimRepository claims,
37:             PeriodRepository periods, RateRepository rates, SettingsRepository settings, ClaimLogRepository log,
38:             HolidayRepository holidays, HttpServletRequest request, Audit audit, Out<PasteResponse> result)
39:             throws InvalidClaimException, ClosedPeriodException, RetiredPersonException {
40:         Settings terms = settings.find(sheet.id());
41:         List<Person> persons = new ArrayList<>();
42:         List<Claim> built = new ArrayList<>();
43:         Set<String> refs = new HashSet<>();
44:         for (PasteLine line : paste.lines()) {
45:             Person person = people.findByName(sheet.id(), line.name());
46:             if (person == null) throw new InvalidClaimException("No one named " + line.name() + " is on the sheet");
47:             LocalDate date = line.claim().date() == null ? terms.entryDay(sheet.today()) : line.claim().date();
48:             Claim claim = new Claim(null, sheet.id(), person.getId(), line.claim().amount(), date, line.claim().note(),
49:                     ClaimStatus.DRAFT, null, null, null);
50:             claim.setRef(line.claim().ref());
51:             if (claim.getRef() != null && !refs.add(claim.getRef().toUpperCase(Locale.ROOT))) {
52:                 throw new InvalidClaimException("The reference " + claim.getRef() + " is pasted more than once");
53:             }
54:             new CheckClaimRef().check(claim, claims);
55:             claim.fixDueBy(terms.termsFor(person, date), holidays.dates(sheet.id()));
56:             new CheckClaimPeriod().check(sheet, claim, periods);
57:             claim.setLateEntry(periods.softClosedOn(sheet.id(), claim.getDueBy()) != null);
58:             new CheckClaimRetired().check(sheet, claim, people);
59:             persons.add(person);
60:             built.add(claim);
61:         }
62:         String user = Audit.user(request);
63:         for (int i = 0; i < built.size(); i++) {
64:             Claim claim = built.get(i);
65:             claims.save(claim);
66:             log.record(claim, user, sheet.today(), LogClaimStatus.due(sheet, claim, people, rates, settings));
67:             new AuditClaimAdded().audit(sheet, persons.get(i), claim, request, audit);
68:         }
69:         result.set(new PasteResponse(built.size()));
70:     }
71: }
