=== claim/AddPlanClaims.java
25: /**
26:  * For every plan on the sheet, in the order they were added, a DRAFT claim with the plan's amount for
27:  * every plan date (its start, then every N days; or monthly on its day of the month) up to its end and the sheet's today that has none yet,
28:  * dated that day with an empty note. Each is checked as the claim form checks a claim (its due-by outside
29:  * a closed period, its date not after its person's retirement): a date refused is skipped, and tried again
30:  * next time. Each claim made is saved, logged and audited as one added by the form.
31:  */
32: public class AddPlanClaims {
33:     public void add(@Val Sheet sheet, PlanRepository plans, PersonRepository people, ClaimRepository claims,
34:             PeriodRepository periods, RateRepository rates, SettingsRepository settings, ClaimLogRepository log,
35:             HolidayRepository holidays, HttpServletRequest request, Audit audit, Out<GenerateResponse> result) {
36:         Settings terms = settings.find(sheet.id());
37:         Set<LocalDate> holidayDates = holidays.dates(sheet.id());
38:         String user = Audit.user(request);
39:         int made = 0;
40:         for (Plan plan : plans.findAll(sheet.id())) {
41:             Person person = people.find(sheet.id(), plan.personId());
42:             if (person == null) continue;
43:             Set<LocalDate> done = plans.made(plan.id());
44:             LocalDate last = plan.end().isBefore(sheet.today()) ? plan.end() : sheet.today();
45:             for (LocalDate date : plan.datesUpTo(last)) {
46:                 if (done.contains(date)) continue;
47:                 Claim claim = new Claim(null, sheet.id(), person.getId(), plan.amount(), date, "",
48:                         ClaimStatus.DRAFT, null, null, null);
49:                 claim.fixDueBy(terms.termsFor(person, date), holidayDates);
50:                 try {
51:                     new CheckClaimPeriod().check(sheet, claim, periods);
52:                     new CheckClaimRetired().check(sheet, claim, people);
53:                 } catch (ClosedPeriodException | RetiredPersonException e) {
54:                     continue;
55:                 }
56:                 claim.setLateEntry(periods.softClosedOn(sheet.id(), claim.getDueBy()) != null);
57:                 claims.save(claim);
58:                 plans.recordMade(plan.id(), date, claim.getId());
59:                 log.record(claim, user, sheet.today(), LogClaimStatus.due(sheet, claim, people, rates, settings));
60:                 new AuditClaimAdded().audit(sheet, person, claim, request, audit);
61:                 made++;
62:             }
63:         }
64:         result.set(new GenerateResponse(made));
65:     }
66: }
