8: /**
9:  * A person's plan on a sheet: an amount with two decimals, made a DRAFT claim on its start date, then
10:  * every {@code every} days or monthly on day {@code day} of the month (the other null), up to its end date. {@code generated} is how many claims it has made so far.
11:  */
12: public record Plan(Long id, String sheetId, long personId, BigDecimal amount, LocalDate start, Integer every,
13:         Integer day, LocalDate end, int generated) {
15:     /**
16:      * The plan dates up to {@code last}, in order: its start then every N days; or, monthly, that day in
17:      * every month from the start's month (a day beyond the month's length falling on its last day),
18:      * dates before the start left out.
19:      */
20:     public List<LocalDate> datesUpTo(LocalDate last) {
21:         List<LocalDate> dates = new ArrayList<>();
22:         if (day != null) {
23:             for (LocalDate month = start.withDayOfMonth(1); !month.isAfter(last); month = month.plusMonths(1)) {
24:                 LocalDate date = month.withDayOfMonth(Math.min(day, month.lengthOfMonth()));
25:                 if (!date.isBefore(start) && !date.isAfter(last)) dates.add(date);
26:             }
27:         } else {
28:             for (LocalDate date = start; !date.isAfter(last); date = date.plusDays(every)) dates.add(date);
29:         }
30:         return dates;
31:     }
33:     /** The first {@code count} plan dates after {@code today} and on or before its end, in order. */
34:     public List<LocalDate> nextDates(LocalDate today, int count) {
35:         return datesUpTo(end).stream().filter(d -> d.isAfter(today)).limit(count).toList();
36:     }
37: }
