11: /**
12:  * A plan needs an amount the claim form would take, a start and an end date (the end not before the
13:  * start; a blank start is the sheet's today, resolved when it is saved) and either every N days, a
14:  * whole number at least 1, or monthly on a day of the month, 1 to 31.
15:  */
16: public class ValidatePlan {
17:     public void validate(@RequestBody PlanRequest request, Out<PlanInput> body) throws InvalidPlanException {
18:         if (request == null) throw new InvalidPlanException("A plan needs an amount, a start, every N days and an end");
19:         ClaimInput claim;
20:         try {
21:             claim = ClaimInput.from(new ClaimRequest(request.amount(), "", "", "", "", ""));
22:         } catch (InvalidClaimException e) {
23:             throw new InvalidPlanException(e.getMessage());
24:         }
25:         LocalDate start = date(request.start(), "A start date");
26:         LocalDate end = date(request.end(), "An end date");
27:         if (end == null) throw new InvalidPlanException("An end date is required");
28:         String rawEvery = request.every() == null ? "" : request.every().trim();
29:         String rawDay = request.day() == null ? "" : request.day().trim();
30:         Integer every = null;
31:         Integer day = null;
32:         if (!rawDay.isEmpty()) {
33:             if (!rawEvery.isEmpty()) throw new InvalidPlanException("A plan runs every N days or on a day of the month, not both");
34:             if (!rawDay.matches("\\d{1,2}") || Integer.parseInt(rawDay) < 1 || Integer.parseInt(rawDay) > 31) {
35:                 throw new InvalidPlanException("The day of the month is a whole number from 1 to 31");
36:             }
37:             day = Integer.parseInt(rawDay);
38:         } else {
39:             if (!rawEvery.matches("\\d{1,6}") || Integer.parseInt(rawEvery) < 1) {
40:                 throw new InvalidPlanException("Every is a whole number of days, at least 1");
41:             }
42:             every = Integer.parseInt(rawEvery);
43:         }
44:         if (start != null && end.isBefore(start)) throw new InvalidPlanException("A plan's end is not before its start");
45:         body.set(new PlanInput(claim.amount(), start, every, day, end));
46:     }
48:     private static LocalDate date(String raw, String what) throws InvalidPlanException {
49:         String value = raw == null ? "" : raw.trim();
50:         if (value.isEmpty()) return null;
51:         try {
52:             return LocalDate.parse(value);
53:         } catch (DateTimeParseException e) {
54:             throw new InvalidPlanException(what + " is yyyy-MM-dd");
55:         }
56:     }
57: }
