8: /**
9:  * A validated claim request. {@code date} is null when left blank: the sheet's entry date while it is set, else its today.
10:  * {@code corrects} is the number of the claim a correction (a negative amount) corrects; null for
11:  * any other claim. {@code ref} is its external reference, trimmed; null when left blank. {@code tags} are its
12:  * tags, each trimmed and lower-cased, repeats dropped, sorted and comma separated; null when none are given.
13:  */
14: public record ClaimInput(BigDecimal amount, LocalDate date, String note, String corrects, String ref, String tags) {
15:     private static final Pattern AMOUNT = Pattern.compile("-?\\d{1,15}(\\.\\d{1,2})?");
16:     private static final Pattern NUMBER = Pattern.compile("\\d{1,9}|.{1,190}-\\d{1,9}");
18:     /** A claim request checked by the claim form's rules. */
19:     public static ClaimInput from(ClaimRequest request) throws InvalidClaimException {
20:         String amount = request == null || request.amount() == null ? "" : request.amount().trim();
21:         if (amount.isEmpty()) throw new InvalidClaimException("An amount is required");
22:         if (!AMOUNT.matcher(amount).matches()) {
23:             throw new InvalidClaimException("An amount is a number with up to two decimals");
24:         }
25:         String rawDate = request.date() == null ? "" : request.date().trim();
26:         LocalDate date = null;
27:         if (!rawDate.isEmpty()) {
28:             try {
29:                 date = LocalDate.parse(rawDate);
30:             } catch (DateTimeParseException e) {
31:                 throw new InvalidClaimException("A date is yyyy-MM-dd");
32:             }
33:         }
34:         String note = request.note() == null ? "" : request.note().trim();
35:         if (note.length() > 1000) throw new InvalidClaimException("A note is at most 1000 characters");
36:         BigDecimal value = new BigDecimal(amount).setScale(2);
37:         String rawCorrects = request.corrects() == null ? "" : request.corrects().trim();
38:         String corrects = null;
39:         if (value.signum() < 0) {
40:             if (rawCorrects.isEmpty()) {
41:                 throw new InvalidClaimException("A negative amount is a correction: name the claim it corrects");
42:             }
43:             if (!NUMBER.matcher(rawCorrects).matches()) {
44:                 throw new InvalidClaimException("A correction names a claim by its number");
45:             }
46:             corrects = rawCorrects;
47:         } else if (!rawCorrects.isEmpty()) {
48:             throw new InvalidClaimException("Only a negative amount corrects a claim");
49:         }
50:         String ref = request.ref() == null ? "" : request.ref().trim();
51:         if (ref.length() > 200) throw new InvalidClaimException("A reference is at most 200 characters");
52:         String tags = tags(request.tags());
53:         if (tags != null && tags.length() > 2000) throw new InvalidClaimException("Tags are at most 2000 characters");
54:         return new ClaimInput(value, date, note, corrects, ref.isEmpty() ? null : ref, tags);
55:     }
57:     /** Comma separated tags, each trimmed and lower-cased, repeats dropped, sorted and comma separated; null when none. */
58:     static String tags(String raw) {
59:         if (raw == null) return null;
60:         java.util.TreeSet<String> tags = new java.util.TreeSet<>();
61:         for (String tag : raw.split(",")) {
62:             String t = tag.trim().toLowerCase(java.util.Locale.ROOT);
63:             if (!t.isEmpty()) tags.add(t);
64:         }
65:         return tags.isEmpty() ? null : String.join(",", tags);
66:     }
67: }
