9: /**
10:  * A grade's rate on a sheet: a percent with two decimals, from a date (null: from the beginning of
11:  * time) through a date (null: with no end). Its level is how far up the sheet's parent chain it is
12:  * set: 0 on the sheet itself, 1 on its parent, up to {@link #MAX_LEVEL}.
13:  */
14: public record Rate(String sheetId, String grade, BigDecimal pct, LocalDate from, LocalDate to, int level) {
16:     /** How many parent sheets up a rate is looked for. */
17:     public static final int MAX_LEVEL = 3;
19:     /** A rate set on the sheet itself. */
20:     public Rate(String sheetId, String grade, BigDecimal pct, LocalDate from, LocalDate to) {
21:         this(sheetId, grade, pct, from, to, 0);
22:     }
24:     /** The same rate seen from a sheet {@code levels} below the one it is set on. */
25:     public Rate up(int levels) {
26:         return new Rate(sheetId, grade, pct, from, to, level + levels);
27:     }
29:     /**
30:      * The grade's rate in force on the date: on the sheet itself, else on its parent, and so on up
31:      * the levels. Empty when no level has one in force.
32:      */
33:     public static Optional<BigDecimal> inForce(List<Rate> rates, String grade, LocalDate date) {
34:         for (int level = 0; level <= MAX_LEVEL; level++) {
35:             Optional<BigDecimal> found = inForce(rates, grade, date, level);
36:             if (found.isPresent()) return found;
37:         }
38:         return Optional.empty();
39:     }
41:     /**
42:      * The grade's rate in force on the date at one level: the one whose from-date is the latest on
43:      * or before it, unless its to-date is before the date. Empty when the date is before every rate
44:      * the grade has there, or after the to-date of the rate that would apply.
45:      */
46:     private static Optional<BigDecimal> inForce(List<Rate> rates, String grade, LocalDate date, int level) {
47:         return rates.stream()
48:                 .filter((r) -> r.level() == level)
49:                 .filter((r) -> r.grade().equals(grade))
50:                 .filter((r) -> r.from() == null || !r.from().isAfter(date))
51:                 .max(Comparator.comparing(Rate::from, Comparator.nullsFirst(Comparator.naturalOrder())))
52:                 .filter((r) -> r.to() == null || !r.to().isBefore(date))
53:                 .map(Rate::pct);
54:     }
55: }
