22: /**
23:  * What a candidate rate would do: for the OPEN and PENDING claims of people on the grade (the one
24:  * in force on the claim's date), how many would show a different due were the grade's rate the
25:  * candidate on every date, and the differences (new due minus current due) added up. A claim bound
26:  * by a statement keeps its figure; n/a counts as nothing. Nothing is saved.
27:  */
28: public class RespondWithPreview {
29:     public void respond(@Val Sheet sheet, @Val PreviewInput preview, PersonRepository people,
30:             ClaimRepository claims, RateRepository rates, SettingsRepository settingsRepository,
31:             ObjectResponse<PreviewResponse> response) {
32:         LocalDate today = sheet.today();
33:         Settings settings = settingsRepository.find(sheet.id());
34:         List<Rate> current = rates.findAll(sheet.id());
35:         List<Rate> candidate = new ArrayList<>(current.stream()
36:                 .filter((r) -> !r.grade().equals(preview.grade())).toList());
37:         candidate.add(new Rate(sheet.id(), preview.grade(), preview.pct(), null, null));
38:         Map<Long, Person> byId = people.findAll(sheet.id()).stream()
39:                 .collect(Collectors.toMap(Person::getId, Function.identity()));
40:         int count = 0;
41:         BigDecimal diff = BigDecimal.ZERO.setScale(2);
42:         for (Claim claim : claims.findAll(sheet.id())) {
43:             if (!claim.isOpen() || claim.isBound()) continue;
44:             Person person = byId.get(claim.getPersonId());
45:             if (person == null) continue;
46:             String grade = person.gradeOn(claim.getDate());
47:             if (!preview.grade().equals(grade)) continue;
48:             BigDecimal was = ClaimFigure.withLate(claim, current, grade, settings, today);
49:             BigDecimal now = ClaimFigure.withLate(claim, candidate, grade, settings, today);
50:             if (Objects.equals(was, now)) continue;
51:             count++;
52:             diff = diff.add(orZero(now)).subtract(orZero(was));
53:         }
54:         response.send(new PreviewResponse(count, diff.setScale(2).toPlainString()));
55:     }
57:     private static BigDecimal orZero(BigDecimal value) {
58:         return value == null ? BigDecimal.ZERO : value;
59:     }
60: }
