31:     /** The pool's pot: the sheet's when it is a member of no pool, else its cut in the pool above (null for none). */
32:     private static BigDecimal pot(String pool, List<PoolMember> members, Map<String, List<PoolMember>> byPool,
33:             BigDecimal sheetPot, Map<String, BigDecimal> pots) {
34:         if (pots.containsKey(pool)) return pots.get(pool);
