14: public class SavePoolMember {
15:     static final int MAX_DEPTH = 3;
17:     public void save(@Val PoolMemberInput input, @Val Sheet sheet, PoolRepository pools, PersonRepository people,
18:             Out<PoolMember> memberOut) throws InvalidPoolException {
19:         Pool pool = pools.find(sheet.id(), input.pool());
20:         if (pool == null) throw new InvalidPoolException("No pool " + input.pool());
21:         if (input.memberPool() != null) {
22:             Pool member = pools.find(sheet.id(), input.memberPool());
23:             if (member == null) throw new InvalidPoolException("No pool " + input.memberPool());
24:             if (member.id().equals(pool.id())) throw new InvalidPoolException("A pool cannot contain itself");
25:             if (pools.parentOf(member) != null) {
26:                 throw new InvalidPoolException(member.name() + " is already a member of a pool");
27:             }
28:             int level = 1;
29:             for (Pool above = pools.parentOf(pool); above != null; above = pools.parentOf(above)) {
30:                 if (above.id().equals(member.id())) throw new InvalidPoolException("A pool cannot contain itself");
31:                 level++;
32:             }
33:             if (level + height(member, pools) > MAX_DEPTH) {
34:                 throw new InvalidPoolException("A chain of pools is at most " + MAX_DEPTH + " deep");
35:             }
36:             pools.addMemberPool(pool, member, input.share(), input.from(), input.to());
37:             memberOut.set(new PoolMember(sheet.id(), pool.name(), null, member.name(), member.name(), input.share(),
38:                     false, false, input.from(), input.to(), PoolMember.covers(input.from(), input.to(), sheet.today())));
39:             return;
40:         }
41:         Person person = people.find(sheet.id(), input.personId());
42:         if (person == null) throw new InvalidPoolException("No such person");
43:         if (pools.isMember(pool, person.getId())) {
44:             throw new InvalidPoolException(person.getName() + " is already in " + pool.name());
45:         }
46:         pools.addMember(pool, person.getId(), input.share(), input.from(), input.to());
47:         memberOut.set(new PoolMember(sheet.id(), pool.name(), person.getId(), null, person.getName(), input.share(),
48:                 person.isRetired(), person.getHolds().stream().anyMatch(h -> h.covers(sheet.today())), input.from(), input.to(),
49:                 PoolMember.covers(input.from(), input.to(), sheet.today())));
50:     }
52:     /** How many pools deep the chain below this pool goes, the pool itself counting as one. */
53:     private static int height(Pool pool, PoolRepository pools) {
54:         int below = 0;
55:         for (Pool m : pools.memberPools(pool)) below = Math.max(below, height(m, pools));
56:         return 1 + below;
