8: /**
9:  * A pool, as the screen reads it: its members in the order added, the total of their shares (a retired
10:  * member's counting as given) and whether that total is exactly 100.00. Each member of a balanced pool
11:  * has a cut of the sheet's pot: the pot times their share divided by the shares of the members with a cut
12:  * added up, rounded half to even to two decimals (a retired member's, and a member held on the sheet's
13:  * today, 0.00), with the remainder, the pot minus the cuts added up, going to the member with the
14:  * smallest non-zero cut, the latest added on a tie (a member with no cut gets none; when no cut is
15:  * non-zero, to the last member with a cut and a share), so the cuts total exactly the pot (each is 0.00
16:  * when no member has a cut). A pool whose every member is retired has no cuts. A hold or a retirement changes neither the total nor whether the pool is balanced. An
17:  * unbalanced pool, or no pot, has no cuts. A member whose dates do not include the sheet's today is
18:  * left out entirely: not in the total, not in the balance, and no cut (not even 0.00). A pool that is a member of another has no pot of its own: its
19:  * pot is its cut in the pool above (none when that pool has no cuts). {@code added} orders the pools as they
20:  * were added (a larger one added later).
21:  */
22: public record PoolResponse(String name, List<PoolMemberResponse> members, String totalShare, boolean balanced,
23:         long added) {
24:     private static final BigDecimal HUNDRED = new BigDecimal("100.00");
26:     public static PoolResponse from(Pool pool, List<PoolMember> members, BigDecimal pot) {
27:         BigDecimal total = total(members);
28:         boolean balanced = total.compareTo(HUNDRED) == 0;
29:         List<BigDecimal> cuts = cutsOf(members, pot);
30:         List<PoolMemberResponse> shown = new ArrayList<>();
31:         for (int i = 0; i < members.size(); i++) {
32:             shown.add(PoolMemberResponse.from(members.get(i), cuts == null ? null : cuts.get(i)));
33:         }
34:         return new PoolResponse(pool.name(), shown, total.toPlainString(), balanced, pool.id());
35:     }
37:     /** The active members' shares added up, a retired member's counting as given. */
38:     static BigDecimal total(List<PoolMember> members) {
39:         BigDecimal total = BigDecimal.ZERO.setScale(2);
40:         for (PoolMember m : members) if (m.active()) total = total.add(m.share());
41:         return total;
42:     }
44:     /**
45:      * Each member's cut of the pot, in the members' order; null when the pool is unbalanced, there is no pot,
46:      * or every member is retired.
47:      */
48:     static List<BigDecimal> cutsOf(List<PoolMember> members, BigDecimal pot) {
49:         boolean allRetired = members.stream().filter(PoolMember::active).allMatch(PoolMember::retired);
50:         return pot != null && !allRetired && total(members).compareTo(HUNDRED) == 0 ? cuts(members, pot) : null;
51:     }
53:     /** Whether the member has a cut: active, neither retired nor held on the sheet's today. */
54:     private static boolean hasCut(PoolMember m) {
55:         return m.active() && !m.retired() && !m.held();
56:     }
58:     private static List<BigDecimal> cuts(List<PoolMember> members, BigDecimal pot) {
59:         BigDecimal shares = BigDecimal.ZERO;
60:         for (PoolMember m : members) if (hasCut(m)) shares = shares.add(m.share());
61:         List<BigDecimal> cuts = new ArrayList<>();
62:         BigDecimal sum = BigDecimal.ZERO.setScale(2);
63:         int smallest = -1;
64:         int lastShared = -1;
65:         for (int i = 0; i < members.size(); i++) {
66:             PoolMember m = members.get(i);
67:             if (!m.active()) {
68:                 cuts.add(null);
69:                 continue;
70:             }
71:             BigDecimal cut = !hasCut(m) || shares.signum() == 0 ? BigDecimal.ZERO.setScale(2)
72:                     : pot.multiply(m.share()).divide(shares, 2, RoundingMode.HALF_EVEN);
73:             cuts.add(cut);
74:             sum = sum.add(cut);
75:             if (!hasCut(m)) continue;
76:             if (m.share().signum() > 0) lastShared = i;
77:             if (cut.signum() != 0 && (smallest < 0 || cut.compareTo(cuts.get(smallest)) <= 0)) smallest = i;
78:         }
79:         int to = smallest >= 0 ? smallest : lastShared;
80:         if (to >= 0 && shares.signum() > 0) cuts.set(to, cuts.get(to).add(pot.subtract(sum)));
81:         return cuts;
82:     }
83: }
