21:  * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
22:  * so tests can assert side-effects by reading that file — the second test-assertion channel
23:  * alongside the UI. The file path + one-record-per-line format is a stable contract, like
24:  * data-testid: features may be rewritten as long as they keep emitting the agreed records.
25:  *
26:  * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
27:  * SYNC) so a test reads the record immediately.
28:  */
29: @Service
30: public class Audit {
32:     /** The lines that only report figures a change moved: they are never marked as made for a delegator. */
33:     private static final Set<String> FIGURES = Set.of("ROLLUP", "TOTALS", "ALERT");
35:     /** A record's head: its event name, then {@code sheet=<id> by=<user>}, the user up to the next field. */
36:     private static final Pattern HEAD = Pattern.compile("^(\\S+) sheet=(\\S+) by=(.*?)(?= [a-z][a-z-]*=|$)");
38:     private final Path file;
39:     private final DelegationRepository delegations;
41:     public Audit(@Value("${app.audit.file:.run/audit.log}") String path, DelegationRepository delegations) {
42:         this.file = Path.of(path);
43:         this.delegations = delegations;
44:     }
46:     /**
47:      * Append one audit record. Tests assert the exact line(s) in the file. A change made by a user acting
48:      * as a steward by a delegation, for the sheet's today, ends with {@code for=<the steward who delegated>}.
49:      */
50:     public synchronized void record(String entry) {
51:         Matcher head = HEAD.matcher(entry);
52:         if (head.find() && !FIGURES.contains(head.group(1))) {
53:             String delegator = delegations.delegatorOf(head.group(2), head.group(3));
54:             if (delegator != null) entry = entry + " for=" + delegator;
55:         }
56:         try {
57:             Path parent = file.toAbsolutePath().getParent();
58:             if (parent != null) {
59:                 Files.createDirectories(parent);
60:             }
61:             Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
62:                     StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
63:         } catch (IOException e) {
64:             throw new UncheckedIOException(e);
65:         }
66:     }
68:     /**
69:      * The signed-in user who made a change, as the screen sends it in the {@code X-User} header
70:      * (URI-encoded, so any name fits a header).
71:      */
72:     public static String user(HttpServletRequest request) {
73:         String header = request.getHeader("X-User");
74:         return header == null ? "" : URLDecoder.decode(header, StandardCharsets.UTF_8);
75:     }
77:     /** A person field of a record: {@code name=} or {@code person=}, its value up to the next field. */
78:     private static final Pattern PERSON = Pattern.compile("(?<= )(?:name|person)=(.*?)(?= [a-z][a-z-]*=|$)");
80:     /**
81:      * The sheet's records as the file holds them, in file order. A non-blank {@code name} keeps only
82:      * the records carrying {@code name=} or {@code person=} that name, case and surrounding spaces ignored.
83:      */
84:     public synchronized List<String> linesFor(String sheetId, String name) {
85:         List<String> all;
86:         try {
87:             all = Files.exists(file) ? Files.readAllLines(file, StandardCharsets.UTF_8) : List.of();
88:         } catch (IOException e) {
89:             throw new UncheckedIOException(e);
90:         }
91:         String wanted = name.trim().toLowerCase(Locale.ROOT);
92:         return all.stream().filter(line -> {
93:             Matcher head = HEAD.matcher(line);
94:             if (!head.find() || !head.group(2).equals(sheetId)) return false;
95:             if (wanted.isEmpty()) return true;
96:             Matcher field = PERSON.matcher(line);
97:             while (field.find()) {
98:                 if (field.group(1).trim().toLowerCase(Locale.ROOT).equals(wanted)) return true;
99:             }
100:             return false;
101:         }).toList();
102:     }
104:     /** Remove the audit file. */
105:     public synchronized void clear() {
106:         try {
107:             Files.deleteIfExists(file);
108:         } catch (IOException e) {
109:             throw new UncheckedIOException(e);
110:         }
111:     }
112: }
